var base=window.yqBrain;
function wrapBase(q){var r=null;try{r=base?base(q):null}catch(e){r=null}return r}
function isGeneric(q,b){var qt=toks(q).filter(function(w){return w.length>2});if(qt.length<2)return false;var txt=(b.x||'')+' '+String(b.h||'').replace(/<[^>]+>/g,' ');if(/^\s*(طريقة الحل|سأفسر السؤال|المجال الأقرب)/.test(b.x||''))return true;return overlap(qt,txt)<.34&&!glossBest(q)}
function notFound(q){var sug=findExps(q,P.grade,'',3),h='<p>لم أجد في قاعدة معرفتي إجابة موثوقة عن «'+esc(q)+'»، ولن أخمّن إجابة قد تكون خطأ.</p>';if(sug.length){h+='<span>مواضيع قريبة في الموقع:</span>';sug.forEach(function(i){h+=expCard(i,false)})}else h+='<p>جرّب كتابة اسم المفهوم أو القانون بكلمة أو كلمتين، مثل: «الكثافة»، «قانون أوم»، «البناء الضوئي».</p>';return {h:h,x:'لا توجد إجابة موثوقة في قاعدة المعرفة.'}}
function enrich(r,q){if(!r||!r.h)return r;var n=nz(q);var weak=/لم أجد في قاعدة معرفتي/.test(r.h);if(weak)return r;var add='';var gl=glossBest(q);
 if(P.role==='student'&&P.grade&&P.grade<=6)r.h='<div class="yqai-note">🧒 بكلمات بسيطة:</div>'+r.h;
 if(gl&&/^(ما|ماذا|شو|عرف|اشرح|ما هو|ما هي|مش فاهم|فهمني)/.test(n)){var rows=findExps(gl[0],P.grade,'',2);var pool=poolExps(rows).filter(function(x){return overlap(toks(gl[0]),x.q+' '+x.o[x.a])>=.3});if(pool.length){var cq=pickQ(pool,1);add+=quizHtml(cq,'سؤال سريع للتأكد من فهمك',{})}}
 if(P.role==='teacher')add+='<div class="yqai-card"><b>👩‍🏫 للمعلم:</b> اعرض التجربة المقترحة على الشاشة، واطلب من الطلاب توقّع النتيجة قبل تغيير المتغير، ثم اطلب «أسئلة مع الإجابات» عن الموضوع لتقويم سريع.</div>';
 r.h+=add;return r}
function ask(q){q=String(q||'').trim();if(!q)return;sayUser(q);pushHist('user',q);var th=thinking();
 setTimeout(function(){var r=null;try{r=router(q)}catch(e){r=null}
  if(!r||r.weak){var b=wrapBase(q);if(b&&b.h){var weakB=/لم أجد في قاعدة معرفتي/.test(b.h)||isGeneric(q,b);if(weakB&&!/لم أجد في قاعدة معرفتي/.test(b.h))b=notFound(q);if(AI.on&&(weakB||(r&&r.weak)||isLatin(q)||q.length>140)){aiAsk(q,th,b.h);return}r=enrich(b,q)}else if(AI.on){aiAsk(q,th,'');return}}
  if(th&&th.parentNode)th.parentNode.removeChild(th);if(!r)r={h:'<p>لم أفهم سؤالك تمامًا، هل يمكنك إعادة صياغته؟</p>'};var extra='';if(AI.on&&!r.solved)extra='<div class="yqai-b"><button type="button" class="g" data-yqai-deep="'+esc(q)+'">🤖 شرح أعمق بالذكاء الاصطناعي</button></div>';
  say(r.h+extra);pushHist('assistant',r.x||'')},180)}
