 if((a=t.getAttribute('data-yqai-copy'))){var tx=QZ[a]&&QZ[a].txt;if(tx){try{navigator.clipboard.writeText(tx).then(function(){t.textContent='✅ تم النسخ'},function(){t.textContent='انسخ يدويًا'})}catch(e){}}return}
