 if((a=t.getAttribute('data-yqai-deep'))){deep(a);return}
 if(t.hasAttribute('data-yqai-clearh')){lsS('yq_ai_hist','[]');say('<p>🗑️ تم مسح سجل الاختبارات من هذا الجهاز.</p>');return}
